import mimetypes
from pathlib import Path

import apps.documents.storage
from django.conf import settings
from django.db import migrations, models


def move_images_into_database(apps, schema_editor):
    """
    Pictures uploaded before this change live on disk. Copy each into the
    database; one whose file is already gone (e.g. wiped by a redeploy) is
    cleared so the landing page shows its placeholder, not a broken image.
    """
    StoredFile = apps.get_model('documents', 'StoredFile')
    media_root = Path(settings.MEDIA_ROOT)
    for model_name in ('Announcement', 'Event'):
        Model = apps.get_model('documents', model_name)
        for item in Model.objects.exclude(image='').exclude(image__isnull=True):
            name = str(item.image)
            path = media_root / name
            if StoredFile.objects.filter(name=name).exists():
                continue
            if path.is_file():
                data = path.read_bytes()
                StoredFile.objects.create(
                    name=name, content=data, size=len(data),
                    content_type=mimetypes.guess_type(name)[0] or 'application/octet-stream',
                )
            else:
                Model.objects.filter(pk=item.pk).update(image='')


